// Fetch pending unfreeze requests and pick first
var baseUrl = pm.collectionVariables.get('baseUrl');
var token = pm.collectionVariables.get('authToken');
pm.sendRequest({
  url: baseUrl + '/api/leave/worklog-unfreeze-requests?status=PENDING&size=5',
  method: 'GET',
  header: { Authorization: 'Bearer ' + token }
}, function(err, res) {
  var fallback = 1461;
  if (err || res.code !== 200) { pm.variables.set('unfreezeRequestId', String(fallback)); return; }
  var body = res.json();
  var arr = Array.isArray(body) ? body : (body.data || body.items || []);
  var pick = arr.length ? arr[0] : null;
  pm.variables.set('unfreezeRequestId', pick ? String(pick.id) : String(fallback));
});
